#include <bits/stdc++.h>using namespace std;using ll = long long; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n;        ll x, y;        cin >> n >> x >> y;         vector<ll> a(n), contrib(n);        for (int i = 0; i < n; i++) {            cin >> a[i];            contrib[i] = (a[i] / x) * y;        }         // prefix sum        vector<ll> prefix(n, 0), suffix(n, 0);        prefix[0] = contrib[0];        for (int i = 1; i < n; i++) {            prefix[i] = prefix[i - 1] + contrib[i];        }         // suffix sum        suffix[n - 1] = contrib[n - 1];        for (int i = n - 2; i >= 0; i--) {            suffix[i] = suffix[i + 1] + contrib[i];        }         ll ans = 0;         for (int i = 0; i < n; i++) {            ll left = (i > 0) ? prefix[i - 1] : 0;            ll right = (i + 1 < n) ? suffix[i + 1] : 0;            ans = max(ans, a[i] + left + right);        }         cout << ans << "\n";    }     return 0;}